use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input: Vec<Vec<Vec<i64>>> = input.into();
    let left = input[0].into_iter().collect::<std::collections::HashMap<_, _>>();
    let right = input[1].into_iter().collect::<std::collections::HashMap<_, _>>();
    let mut common: Vec<Vec<i64>> = Vec::new();

    for (key, left_value) in &left {
        if let Some(&right_value) = right.get(key) {
            common.push(vec![key.to_string().parse().unwrap(), *left_value, right_value]);
        }
    }

    common.sort_by(|a, b| a[0].cmp(&b[0]));

    Value::Array(common.into_iter().map(|mut v| {
        v.drain(1..).collect::<Vec<_>>()
    }).collect())
}
